export declare const css = "/* =========================================================================\n   Pulse Shared Navigation \u2014 sidebar styles (Synapse / HMIS design system).\n   Every class is prefixed `psn-` so it can't collide with the host app.\n   Override any --psn-* variable on `.psn-root` (or :root) to theme it.\n   ========================================================================= */\n\n.psn-root,\n.psn-menu-btn,\n.psn-toast {\n  --psn-sidebar-w: 272px;\n  --psn-z: 40;\n  --psn-font: 'Urbanist', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;\n  --psn-bg: linear-gradient(165deg, #064642 0%, #023635 62%, #03251f 100%);\n  --psn-accent: #40ffb8;\n  --psn-accent-2: #4bb69a;\n  --psn-deep: #023635;\n  --psn-text: #ffffff;\n  --psn-overlay: rgba(3, 17, 15, 0.58);\n  --psn-shadow: 0 30px 70px rgba(76, 73, 105, 0.19), inset 0 1px 0 rgba(255, 255, 255, 0.9);\n  --psn-radius: 8px;\n  --psn-radius-lg: 12px;\n  --psn-ease-settle: cubic-bezier(0.16, 1, 0.3, 1);\n  --psn-ease-enter: cubic-bezier(0.2, 0.7, 0.2, 1);\n  --psn-ease-exit: cubic-bezier(0.4, 0, 0.7, 0.2);\n  --psn-fast: 180ms;\n  --psn-base: 300ms;\n  --psn-overlay-dur: 560ms;\n  font-family: var(--psn-font);\n}\n\n.psn-root *,\n.psn-root *::before,\n.psn-root *::after {\n  box-sizing: border-box;\n}\n\n/* ---------------- Shell ---------------- */\n.psn-sidebar {\n  width: var(--psn-sidebar-w);\n  max-width: 88vw;\n  background: var(--psn-bg);\n  color: var(--psn-text);\n  display: flex;\n  flex-direction: column;\n  position: fixed;\n  left: 0;\n  top: 0;\n  height: 100vh;\n  height: 100dvh;\n  transform: translateX(-100%);\n  transition: transform var(--psn-overlay-dur) var(--psn-ease-exit), box-shadow var(--psn-overlay-dur) var(--psn-ease-exit);\n  z-index: var(--psn-z);\n  overflow: hidden;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n\n.psn-sidebar::before,\n.psn-sidebar::after {\n  content: '';\n  position: absolute;\n  border-radius: 50%;\n  pointer-events: none;\n}\n\n.psn-sidebar::before {\n  top: -120px;\n  right: -140px;\n  width: 320px;\n  height: 320px;\n  background: radial-gradient(closest-side, rgba(64, 255, 184, 0.22), transparent);\n}\n\n.psn-sidebar::after {\n  bottom: -140px;\n  left: -100px;\n  width: 280px;\n  height: 280px;\n  background: radial-gradient(closest-side, rgba(141, 115, 222, 0.12), transparent);\n}\n\n.psn-root.open .psn-sidebar {\n  transform: translateX(0);\n  box-shadow: var(--psn-shadow);\n  transition: transform var(--psn-overlay-dur) var(--psn-ease-settle), box-shadow var(--psn-overlay-dur) var(--psn-ease-settle);\n}\n\n.psn-backdrop {\n  position: fixed;\n  inset: 0;\n  background: var(--psn-overlay);\n  z-index: calc(var(--psn-z) - 5);\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity var(--psn-overlay-dur) var(--psn-ease-exit);\n}\n\n.psn-root.open .psn-backdrop {\n  opacity: 1;\n  pointer-events: auto;\n  transition: opacity var(--psn-overlay-dur) var(--psn-ease-enter);\n}\n\n/* Docked: always visible on wide screens; the host offsets its content with\n   `padding-left: var(--psn-sidebar-w)` (or the .psn-docked-offset helper). */\n@media (min-width: 1024px) {\n  .psn-docked .psn-sidebar {\n    transform: none;\n    box-shadow: none;\n  }\n  .psn-docked .psn-backdrop,\n  .psn-docked .psn-collapse {\n    display: none;\n  }\n  .psn-docked-offset {\n    padding-left: var(--psn-sidebar-w, 272px);\n  }\n}\n\n.psn-top {\n  height: 3px;\n  background: linear-gradient(90deg, var(--psn-accent), var(--psn-accent-2));\n  flex-shrink: 0;\n  position: relative;\n  z-index: 1;\n}\n\n/* ---------------- Header ---------------- */\n.psn-header {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 22px 18px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n  flex-shrink: 0;\n  position: relative;\n  z-index: 1;\n}\n\n.psn-logo-btn {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n  flex: 1;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 0;\n  color: inherit;\n  font: inherit;\n  text-align: left;\n}\n\n.psn-logo-btn:disabled {\n  cursor: default;\n}\n\n.psn-logo {\n  width: 38px;\n  height: 38px;\n  border-radius: var(--psn-radius-lg);\n  background: linear-gradient(150deg, var(--psn-accent), var(--psn-accent-2));\n  color: var(--psn-deep);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  box-shadow: 0 6px 16px rgba(2, 54, 53, 0.35);\n  overflow: hidden;\n}\n\n.psn-logo img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.psn-brand {\n  overflow: hidden;\n  white-space: nowrap;\n  min-width: 0;\n}\n\n.psn-brand .n {\n  display: block;\n  font-size: 16px;\n  font-weight: 700;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  letter-spacing: -0.01em;\n}\n\n.psn-brand .s {\n  display: block;\n  font-size: 9.5px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.55);\n  letter-spacing: 0.14em;\n  margin-top: 2px;\n}\n\n.psn-collapse {\n  margin-left: auto;\n  width: 28px;\n  height: 28px;\n  border-radius: var(--psn-radius);\n  border: none;\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--psn-text);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  flex-shrink: 0;\n  transition: background var(--psn-base) var(--psn-ease-enter);\n}\n\n.psn-collapse:hover {\n  background: rgba(255, 255, 255, 0.18);\n}\n\n/* ---------------- Search ---------------- */\n.psn-search {\n  padding: 16px 16px 10px;\n  flex-shrink: 0;\n  position: relative;\n  z-index: 1;\n}\n\n.psn-search-in {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: rgba(255, 255, 255, 0.08);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: var(--psn-radius-lg);\n  padding: 9px 11px;\n  transition: background var(--psn-fast) var(--psn-ease-enter), border-color var(--psn-fast) var(--psn-ease-enter);\n}\n\n.psn-search-in:focus-within {\n  background: rgba(255, 255, 255, 0.12);\n  border-color: var(--psn-accent);\n}\n\n.psn-search-in svg {\n  color: rgba(255, 255, 255, 0.55);\n  flex-shrink: 0;\n}\n\n.psn-search-in input {\n  background: none;\n  border: none;\n  outline: none;\n  color: var(--psn-text);\n  font: inherit;\n  font-size: 13px;\n  width: 100%;\n  padding: 0;\n}\n\n.psn-search-in input::placeholder {\n  color: rgba(255, 255, 255, 0.48);\n}\n\n/* ---------------- Nav ---------------- */\n.psn-nav {\n  flex: 1;\n  overflow-y: auto;\n  padding: 6px 12px 16px;\n  position: relative;\n  z-index: 1;\n}\n\n.psn-nav::-webkit-scrollbar {\n  width: 4px;\n}\n\n.psn-nav::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.16);\n  border-radius: 4px;\n}\n\n.psn-nav mark {\n  background: rgba(64, 255, 184, 0.28);\n  color: inherit;\n  border-radius: 2px;\n}\n\n.psn-item {\n  margin-bottom: 4px;\n}\n\n.psn-row {\n  position: relative;\n  width: 100%;\n  display: flex;\n  align-items: flex-start;\n  gap: 11px;\n  padding: 10px 12px;\n  border-radius: var(--psn-radius);\n  cursor: pointer;\n  color: rgba(255, 255, 255, 0.82);\n  transition: background var(--psn-fast) var(--psn-ease-enter), color var(--psn-fast) var(--psn-ease-enter);\n}\n\n.psn-row:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--psn-text);\n}\n\n.psn-row.current {\n  background: rgba(255, 255, 255, 0.1);\n  color: var(--psn-text);\n}\n\n.psn-row.current::before {\n  content: '';\n  position: absolute;\n  left: -12px;\n  top: 8px;\n  bottom: 8px;\n  width: 3px;\n  border-radius: 0 4px 4px 0;\n  background: var(--psn-accent);\n}\n\n.psn-item.expanded > .psn-row {\n  background: rgba(64, 255, 184, 0.14);\n  color: var(--psn-text);\n}\n\n.psn-row:focus-visible,\n.psn-app:focus-visible,\n.psn-star:focus-visible,\n.psn-logo-btn:focus-visible,\n.psn-collapse:focus-visible {\n  outline: 2px solid var(--psn-accent);\n  outline-offset: 1px;\n}\n\n.psn-row-icon {\n  width: 19px;\n  height: 19px;\n  flex-shrink: 0;\n  display: flex;\n  margin-top: 1px;\n}\n\n.psn-label {\n  font-size: 13.5px;\n  font-weight: 600;\n  flex: 1;\n  line-height: 1.35;\n  overflow-wrap: break-word;\n}\n\n.psn-count {\n  font-size: 10.5px;\n  font-weight: 700;\n  padding: 2px 7px;\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.14);\n  margin-top: 1px;\n  flex-shrink: 0;\n}\n\n.psn-item.expanded > .psn-row .psn-count {\n  background: rgba(2, 54, 53, 0.35);\n  color: var(--psn-accent);\n}\n\n.psn-chev {\n  width: 13px;\n  height: 13px;\n  flex-shrink: 0;\n  margin-top: 3px;\n  transition: transform var(--psn-base) var(--psn-ease-enter);\n  color: rgba(255, 255, 255, 0.5);\n}\n\n.psn-item.expanded .psn-chev {\n  transform: rotate(90deg);\n  color: var(--psn-accent);\n}\n\n.psn-sub {\n  max-height: 0;\n  overflow: hidden;\n  transition: max-height var(--psn-base) var(--psn-ease-enter);\n  padding-left: 14px;\n}\n\n.psn-item.expanded .psn-sub {\n  max-height: 900px;\n}\n\n.psn-app {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 8px 8px 22px;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.85);\n  border-radius: var(--psn-radius);\n  cursor: pointer;\n  transition: background var(--psn-fast) ease, color var(--psn-fast) ease;\n}\n\n.psn-app:hover {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--psn-text);\n}\n\n.psn-app.current {\n  color: var(--psn-accent);\n}\n\n.psn-app:hover .psn-star {\n  opacity: 1;\n}\n\n.psn-app.disabled {\n  cursor: not-allowed;\n  opacity: 0.5;\n}\n\n.psn-app-name {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.psn-star {\n  width: 20px;\n  height: 20px;\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: rgba(255, 255, 255, 0.35);\n  border-radius: var(--psn-radius);\n  cursor: pointer;\n  opacity: 0.5;\n  transition: color var(--psn-base) var(--psn-ease-enter), opacity var(--psn-base) var(--psn-ease-enter);\n}\n\n.psn-star:hover,\n.psn-star.pinned {\n  color: var(--psn-accent);\n}\n\n.psn-star.pinned {\n  opacity: 1;\n}\n\n.psn-star.pending {\n  pointer-events: none;\n  opacity: 0.4;\n}\n\n.psn-empty {\n  padding: 14px 10px;\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.6);\n  text-align: center;\n}\n\n.psn-retry {\n  display: block;\n  margin: 10px auto 0;\n  padding: 6px 12px;\n  border-radius: var(--psn-radius);\n  border: 1px solid rgba(255, 255, 255, 0.2);\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--psn-text);\n  font: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.psn-retry:hover {\n  border-color: var(--psn-accent);\n}\n\n.psn-skeleton-row {\n  height: 38px;\n  margin-bottom: 6px;\n  border-radius: var(--psn-radius);\n  background: linear-gradient(90deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.11), rgba(255, 255, 255, 0.05));\n  background-size: 200% 100%;\n  animation: psn-shimmer 1.4s ease-in-out infinite;\n}\n\n@keyframes psn-shimmer {\n  from {\n    background-position: 100% 0;\n  }\n  to {\n    background-position: -100% 0;\n  }\n}\n\n.psn-icon-mono {\n  display: inline-block;\n  background-color: currentColor;\n  mask-repeat: no-repeat;\n  mask-position: center;\n  mask-size: contain;\n  -webkit-mask-repeat: no-repeat;\n  -webkit-mask-position: center;\n  -webkit-mask-size: contain;\n}\n\n/* ---------------- Footer ---------------- */\n.psn-footer {\n  padding: 14px 16px;\n  border-top: 1px solid rgba(255, 255, 255, 0.1);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-shrink: 0;\n  position: relative;\n  z-index: 1;\n}\n\n.psn-avatar {\n  width: 32px;\n  height: 32px;\n  border-radius: 50%;\n  background: linear-gradient(150deg, var(--psn-accent), var(--psn-accent-2));\n  color: var(--psn-deep);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 12px;\n  font-weight: 700;\n  flex-shrink: 0;\n}\n\n.psn-user {\n  overflow: hidden;\n  white-space: nowrap;\n  min-width: 0;\n}\n\n.psn-user .un {\n  font-size: 12.5px;\n  font-weight: 700;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.psn-user .ur {\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.55);\n}\n\n/* ---------------- Menu button & toast ---------------- */\n.psn-menu-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 40px;\n  height: 40px;\n  border-radius: var(--psn-radius);\n  border: 1px solid rgba(15, 23, 42, 0.1);\n  background: #ffffff;\n  color: #0f172a;\n  cursor: pointer;\n  flex-shrink: 0;\n  transition: border-color var(--psn-fast) ease, color var(--psn-fast) ease;\n}\n\n.psn-menu-btn:hover {\n  border-color: #82d2ba;\n  color: #126e5c;\n}\n\n.psn-toast {\n  position: fixed;\n  left: 50%;\n  bottom: 24px;\n  transform: translateX(-50%);\n  z-index: calc(var(--psn-z) + 10);\n  max-width: min(420px, calc(100vw - 32px));\n  padding: 10px 16px;\n  border-radius: var(--psn-radius-lg);\n  background: #0f172a;\n  color: #ffffff;\n  font-size: 13px;\n  font-weight: 600;\n  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.18);\n  cursor: pointer;\n}\n\n/* Floating menu button used by <PulseShell>. */\n.psn-floating-menu {\n  position: fixed;\n  left: 12px;\n  bottom: 16px;\n  z-index: calc(var(--psn-z) - 6);\n  width: 44px;\n  height: 44px;\n  border-radius: 50%;\n  border: none;\n  background: linear-gradient(165deg, #064642, #023635);\n  color: #ffffff;\n  box-shadow: 0 10px 22px rgba(2, 54, 53, 0.3);\n}\n\n.psn-floating-menu:hover {\n  color: var(--psn-accent);\n}\n\n@media (min-width: 1024px) {\n  .psn-floating-menu-docked {\n    display: none;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .psn-sidebar,\n  .psn-backdrop,\n  .psn-sub,\n  .psn-chev,\n  .psn-skeleton-row {\n    transition-duration: 0.001ms !important;\n    animation-duration: 0.001ms !important;\n  }\n}\n";
